<?php $cues=music_library_cues_current($selected);$cueDuration=$selectedMetadata['durationSeconds']??0;$cueDefaults=['start'=>0,'vocalStart'=>null,'transition'=>null,'end'=>floor($cueDuration*1000)/1000];$cueValues=$cues['points']??$cueDefaults;?>
<section id="cue-points" class="library-cue-editor" data-cue-editor data-source-url="/music-library-audio.php?id=<?=escape($selected['id'])?>&amp;version=<?=escape($selected['sha256'])?>" data-version="<?=escape($selected['sha256'])?>" data-duration="<?=escape((string)$cueDuration)?>" data-editable="<?=$canUpload?'yes':'no'?>">
<h3>Cue-punkter</h3><p>Sett start, vokalstart, overgang og slutt. Originalen beholdes urørt.</p>
<?php if($selectedMetadata&&$selected['available']):?>
<p class="small"><?=$cues?'Lagrede manuelle punkter. Endringer må lagres før de gjelder ved neste besøk.':'Ingen punkter lagret. Start og slutt viser hele låten; vokalstart og overgang er ukjent.'?></p>
<?php if($canListen):?><button type="button" data-cue-load>Last lydbølge</button><?php endif;?>
<canvas id="cue-waveform" height="180" role="img" aria-label="Lydbølge med cue-markører. Bruk tidsfeltene nedenfor for tastaturbetjening."></canvas>
<p id="cue-status" role="status" class="small">Lydbølgen lastes først når du velger det. Ingen avspilling starter.</p>
<form id="cue-form" method="post"><input type="hidden" name="action" value="cues"><input type="hidden" name="csrf" value="<?=escape($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=escape($selected['id'])?>"><input type="hidden" name="version" value="<?=escape($selected['sha256'])?>"><input type="hidden" name="revision" value="<?=escape((string)($selected['revision']??0))?>">
<div class="cue-fields"><?php foreach(['start'=>'Start','vocalStart'=>'Vokalstart','transition'=>'Overgang','end'=>'Slutt']as$key=>$label):?><div class="cue-field" data-cue-field="<?=$key?>"><label for="cue-<?=$key?>"><?=$label?> · sekunder</label><input id="cue-<?=$key?>" name="<?=$key?>" type="number" min="0" max="<?=escape((string)$cueDuration)?>" step="0.001" <?=in_array($key,['start','end'],true)?'required':''?> value="<?=escape($cueValues[$key]===null?'':(string)$cueValues[$key])?>" <?=$canUpload?'':'disabled'?>><?php if($canUpload):?><button type="button" data-cue-select="<?=$key?>" aria-pressed="<?=$key==='start'?'true':'false'?>">Flytt på lydbølgen</button><button type="button" data-cue-now="<?=$key?>">Sett ved avspillingsposisjon</button><?php endif;?></div><?php endforeach;?></div>
<p class="small">Tomme felt for vokalstart/overgang betyr ukjent. Velg en markør og dra eller trykk på lydbølgen. Tidsfeltene kan også brukes uten lydbølge.</p>
<?php if($canUpload):?><button type="submit" class="button">Lagre cue-punkter</button><?php endif;?></form>
<?php if($canListen):?><div class="cue-preview-actions"><button type="button" data-cue-preview="start">▶ Lytt fra startpunkt</button><button type="button" data-cue-preview="transition">▶ Lytt til overgangen</button><button type="button" data-cue-stop>Stopp cue-lytting</button></div><p class="small">Prøver gjeldende feltverdier i denne nettleseren. Overgangslytting begynner fem sekunder før overgangspunktet. Lyttingen stopper ved sluttpunktet. Ingen miks, kø eller sending.</p><?php endif;?>
<?php else:?><p>Les filopplysninger og varighet før du redigerer cue-punkter.</p><?php endif;?></section>
